"""
@package mocaxpy.MocaxNs
MocaxNs module.

Exports the MocaxNs class.
"""

import mocaxpy.MocaxCInterface
from mocaxpy.MocaxException import *
from mocaxpy.MocaxDomain import *
from mocaxpy.MocaxSpecialPoints import *
import copy
import math
import ctypes


class MocaxNs(object):
    """
    A set of Mocax accuracy parameters.

    Encapsulates the Ns of a Mocax function, used as accuracy parameters.
    """

    def __init__(self, n):
        """
        Constructs a complex set of accuracy parameters (one or several Ns per dimension) from a bidimensional container.

        @param[in] n A list or tuple containing a set of accuracy parameters.
                     <tt>len(n)</tt> is the number of dimensions of the set. A natural number in the range [1,58].
                     Allowed types: @c list, @c tuple; contents allowed types: @c int, @c long, @c list, @c tuple
        """

        # Validation
        if not isinstance(n, (list, tuple)):
            raise TypeError("n has to be a list or a tuple")
        if len(n) < 1:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_NOT_ALLOWED, "The accuracy parameters dimensionality cannot be less than 1. len(n) = " +
                                 str(len(n)))
        i = 0
        multiple_sizes_per_dimension = False
        for n_i in n:
            if isinstance(n_i, (list, tuple)):
                if len(n_i) < 1:
                    raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_NOT_ALLOWED, "The accuracy parameters need at least one N per dimension. len(n[" +
                                         str(i) + "]) = " + str(len(n_i)))
                elif len(n_i) > 1:
                    multiple_sizes_per_dimension = True
                    j = 0
                    for n_i_j in n_i:
                        if n_i_j < 1:
                            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_N_LOWER_THAN_1, "The accuracy parameters cannot be less than 1. n[" +
                                                 str(i) + "][" + str(j) + "] = " + n_i_j)
                        j += 1
                else:
                    if n_i[0] < 1:
                        raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_N_LOWER_THAN_1, "The accuracy parameters cannot be less than 1. n[" +
                                             str(i) + "] = " + str(n_i))
            elif isinstance(n_i, (int, long, str)):
                n_i = long(n_i)
                if n_i < 1:
                    raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_N_LOWER_THAN_1, "The accuracy parameters cannot be less than 1. n[" + str(i) + "] = " +
                                         str(n_i))
            else:
                raise TypeError("n[" + str(i) + "] has to be a list, tuple, integer, or string parseable to integer. " +
                                type(n_i).__name__ + " found instead")
            i += 1

        # Construction
        self.__setup(len(n))
        self.__multiple_sizes_per_dimension = multiple_sizes_per_dimension
        for n_i in n:
            entry = None
            if self.__multiple_sizes_per_dimension:
                entry = []
                if isinstance(n_i, (list, tuple)):
                    for n_i_j in n_i:
                        entry.append(long(n_i_j))
                else:
                    entry.append(long(n_i))
            else:
                entry = [long(n_i)]
            self.__sizes.append(entry)

    def get_num_dimensions(self):
        """
        Gets the number of dimensions of this set.

        @return The number of dimensions of this set.
                Return type: @c int
        """

        return self.__numDimensions

    def has_multiple_sizes_per_dimension(self):
        """
        Gets whether the set has several Ns per dimension or just one.

        @return @c True if the set has several Ns in at least one dimension.
                Return type: @c bool
        """
        return self.__multiple_sizes_per_dimension

    def get_num_ns_for_dimension(self, dimension):
        """
        Gets the number of accuracy parameters associated to a given dimension.

        @param[in] dimension The index (0-based) of the dimension to query.
                             An integer number in the range [0,getNumDimensions()).
                             Allowed types: @c int, @c long
        @return The number of accuracy parameters associated to the given dimension.
                Return type: @c int
        """

        if not isinstance(dimension, (int, long, str)):
            raise TypeError("dimension has to be an integer or a string parseable as an integer")
        dimension = int(dimension)
        if dimension < 0 or dimension >= self.get_num_dimensions():
            raise IndexError("dimension (" + str(dimension) + ") is out of the range [0, " +
                             str(self.get_num_dimensions() - 1) + "]")
        return len(self.__sizes[dimension])

    def get_n(self, dimension, index):
        """
        Gets one of the Ns associated to an specific dimension.

        @param[in] dimension The index (0-based) of the dimension to query.
                             An integer number in the range [0,getNumDimensions()).
                             Allowed types: @c int, @c long
        @param[in] index The index (0-based) of the N in the given dimension.
                         An integer number in the range [0,getNumNsForDimension(dimension)).
                         Allowed tpes: @c int, @c long
        @return The requested accuracy parameter.
                Return type: @c int
        """

        if not isinstance(dimension, (int, long, str)):
            raise TypeError("dimension has to be an integer or a string parseable as an integer")
        dimension = int(dimension)
        if dimension < 0 or dimension >= self.get_num_dimensions():
            raise IndexError("dimension (" + str(dimension) + ") is out of the range [0, " +
                             str(self.get_num_dimensions() - 1) + "]")
        if not isinstance(index, (int, long, str)):
            raise TypeError("index has to be an integer or a string parseable as an integer")
        index = int(index)
        if index < 0 or index >= self.get_num_ns_for_dimension(dimension):
            raise IndexError("index (" + str(index) + ") is out of the range [0, " +
                             str(self.get_num_ns_for_dimension(dimension) - 1) + "]")
        return self.__sizes[dimension][index]

    def make_explicit(self, domain, specialPoints):
        """
        Makes explicit any implicit accuracy parameter (a single N when there are special points in that dimension).

        If the number of dimensions of this set of Ns is one less than the number of
         dimensions of the special points, the first dimension will be omitted.
        @param[in] domain The function domain. Allowed types: mocaxpy.MocaxDomain.MocaxDomain
        @param[in] specialPoints A set of special points. Allowed types: mocaxpy.MocaxSpecialPoints.MocaxSpecialPoints
        """

        if not isinstance(domain, MocaxDomain):
            raise TypeError("domain expected type is MocaxDomain. " + type(domain).__name__ + " received instead")
        if not isinstance(specialPoints, MocaxSpecialPoints):
            raise TypeError("specialPoints expected type is MocaxSpecialPoints. " +
                            type(specialPoints).__name__ + " received instead")

        ignore_first_dimension = False
        offset = 0
        if domain.get_num_dimensions() == self.__numDimensions + 1:
            ignore_first_dimension = True
            offset = 1
        from mocaxpy.MocaxInputsValidator import mocax_validate_domain_ns_special_points
        mocax_validate_domain_ns_special_points(domain, self, specialPoints, ignore_first_dimension)

        for i in range(0, self.__numDimensions):
            if (specialPoints.get_num_special_points_for_dimension(i + offset) > 0 and
                        self.get_num_ns_for_dimension(i) == 1):
                temp_sizes= []
                domain_width = domain.get_width(i + offset)
                segment_width = specialPoints.get_point(i + offset, 0) - domain.get_x_min(i + offset)
                temp_sizes.append(int(math.ceil(self.__sizes[i][0] * segment_width / domain_width)))
                for j in range(0, specialPoints.get_num_special_points_for_dimension(i + offset) - 1):
                    segment_width = specialPoints.get_point(i + offset, j + 1) - specialPoints.get_point(i + offset, j)
                    temp_sizes.append(int(math.ceil(self.__sizes[i][0] * segment_width / domain_width)))
                segment_width = domain.get_x_max(i + offset) - specialPoints.get_point(i + offset,
                                specialPoints.get_num_special_points_for_dimension(i + offset) - 1)
                temp_sizes.append(int(math.ceil(self.__sizes[i][0] * segment_width / domain_width)))
                self.__sizes[i] = temp_sizes
                self.__multiple_sizes_per_dimension = True

    def export_as_multidimensional_array(self):
        """
        Exports the set as a bidimensional C array.

        @note This method is meant to be used internally. For a Python-friendly approach, use export_as_list() instead.

        @return A C-friendly structure containing the accuracy parameters.
                Return type: <tt>ctypes.POINTER(ctypes.c_int64)</tt>
        """

        val = (ctypes.POINTER(ctypes.c_int64) * len(self.__sizes))()
        for i,v in enumerate(self.__sizes):
            val[i] = (ctypes.c_int64 * len(v))(*v)
        return val

    def export_as_list(self):
        """
        Exports the Ns as a native Python list.

        @return A list containing every accuracy parameter.
                Return type: @c list
        """

        return copy.deepcopy(self.__sizes)

    def __str__(self):
        """
        Gets a string representation of this set of accuracy parameters.
        @return The accuracy parameters in string format.
                Return type: @c str
        """
        return str(self.export_as_list())

    def __init(self):
        self.__numDimensions = 0
        self.__multiple_sizes_per_dimension = False
        self.__sizes = []

    def __setup(self, num_dimensions):
        self.__init()

        self.__numDimensions = num_dimensions
        self.__sizes = []
